 for typ in ['v','h']:
  pairs=[]
  for r in range(n):
   for c in range(m):
    rr,cc=(31-r,c) if typ=='v' else (r,31-c)
    if 0<=rr<n and 0<=cc<m and a[r,c]!=8 and a[rr,cc]!=8:
     pairs.append((a[r,c]==a[rr,cc],a[r,c],a[rr,cc]))
  print(typ,sum(x[0] for x in pairs),len(pairs),sum(x[0] for x in pairs)/len(pairs))
