def reflected_candidate(G, box, axis):
 r0,r1,c0,c1=box
 if axis=='v':
  return [[G[31-r][c] if 0<=31-r<len(G) else 8 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
 return [[G[r][31-c] if 0<=31-c<len(G[0]) else 8 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
def box8(G):
 pts=[(r,c) for r,row in enumerate(G) for c,x in enumerate(row) if x==8]
 return min(r for r,c in pts),max(r for r,c in pts),min(c for r,c in pts),max(c for r,c in pts)
def score_axis(G,axis):
 n=len(G);m=len(G[0]); agree=total=0
 for r in range(n):
  for c in range(m):
   rr,cc=(31-r,c) if axis=='v' else (r,31-c)
   if 0<=rr<n and 0<=cc<m and G[r][c]!=8 and G[rr][cc]!=8:
    total+=1;agree+=G[r][c]==G[rr][cc]
 return agree/total if total else 0
for name,G,O in [('d1',g1,o1),('d2',grid,out),('d3',g3,out3),('d4',g4,out4)]:
 box=box8(G)
 sv,sh=score_axis(G,'v'),score_axis(G,'h')
 axis='v' if sv>=sh else 'h'
 cand=reflected_candidate(G,box,axis)
 print(name,box,sv,sh,axis,'match',cand==O,'cand',cand==O)

def transform_guess(G):
 n=len(G);m=len(G[0]);r0,r1,c0,c1=box8(G)
 av,ah=score_axis(G,'v'),score_axis(G,'h')
 axes=['v','h'] if av>=ah else ['h','v']
 out=[]
 for r in range(r0,r1+1):
  row=[]
  for c in range(c0,c1+1):
   val=None
   for axis in axes:
    rr,cc=(31-r,c) if axis=='v' else (r,31-c)
    if 0<=rr<n and 0<=cc<m and G[rr][cc]!=8:
     val=G[rr][cc];break
   if val is None and 0<=c<n and 0<=r<m and G[c][r]!=8:
    val=G[c][r]
   if val is None: val=0
   row.append(val)
  out.append(row)
 return out
for name,G,O in [('d1',g1,o1),('d2',grid,out),('d3',g3,out3),('d4',g4,out4)]:
 C=transform_guess(G); print(name,C==O, C)
